   if(!queued)return{resource:null,version:this.sequence(),status:200};
   const d=JSON.parse(queued.data);
   Object.assign(d,{status:'leased',attemptId:crypto.randomUUID(),runnerId:a.id,leaseExpiresAt:Date.now()+e.payload.leaseSeconds*1000});
