  const cached=this.ctx.storage.sql.exec<{payload:string;response:string;status:number}>('SELECT payload,response,status FROM idempotency WHERE key=?',key).toArray()[0];
  if(cached){if(cached.payload!==payload)throw new HttpFailure('IDEMPOTENCY_CONFLICT','Request id reused with a different payload',409);return json(JSON.parse(cached.response),cached.status);}
  const existing=this.get(id,'source-job'),job=jobResourceSchema.parse(this.resource(existing)).data,input=job.input;
  if(job.input.kind==='composition'&&e.payload.manifestDigest!==job.input.manifestDigest)throw new HttpFailure('INVALID_MANIFEST','Composition manifest digest must match reserved job',422);
