 private async completeJob(r:Request,a:Actor,id:string):Promise<Response>{
  const e=await this.body<z.infer<typeof jobCompleteInput>>(r,jobCompleteInput);
  if(a.role!=='runner')return fail('FORBIDDEN','Runner role required',403);
  if(e.payload.ok&&this.getOptional('policy')&&JSON.parse(this.getOptional('policy')!.data).sourceBackend==='artifacts-git')return fail('SOURCE_BACKEND_MISMATCH','Successful local completion cannot satisfy Artifacts source policy',409);
  return this.transact('runner.complete',a,e,()=>{
   const job=this.get(id,'source-job'),d=jobResourceSchema.parse(this.resource(job)).data;
   if(d.status!=='leased'||d.runnerId!==a.id||d.attemptId!==e.payload.attemptId||d.leaseExpiresAt===null||d.leaseExpiresAt<=Date.now())throw new HttpFailure('LEASE_CONFLICT','Lease is expired or does not belong to this attempt',409);
   const receipt=e.payload.ok?e.payload.receipt:null;
   if(receipt){
    if(receipt.ref!==sourceRef(d.input))throw new HttpFailure('INVALID_RECEIPT','Receipt reference does not match job',422);
    const source=d.input.kind==='seed'?d.input.source:d.input.kind==='publication'?d.input.revision:null;
    if(source&&(source.commitOid!==receipt.commitOid||source.treeOid!==receipt.treeOid))throw new HttpFailure('INVALID_RECEIPT','Receipt does not match exact source',422);
   }
   d.status=e.payload.ok?'completed':'failed';d.receipt=receipt;d.error=e.payload.ok?null:e.payload.error;d.leaseExpiresAt=null;
   if(d.input.kind==='seed'&&receipt){
    if(this.getOptional('baseline'))throw new HttpFailure('CONFLICT','Baseline already initialized',409);
    this.put('baseline',crypto.randomUUID(),a.id,baselineSchema.parse({version:1,commitOid:receipt.commitOid,treeOid:receipt.treeOid,receipt}));
   }else if(d.input.kind==='publication'){
    const changeRow=this.get(d.input.revision.changeId,'change'),change=changeDataSchema.parse(JSON.parse(changeRow.data)),revisionId=d.input.revision.revisionId;
    const revision=change.revisions.find(x=>x.revisionId===revisionId);
    if(!revision||revision.status!=='reserved'||revision.jobId!==id)throw new HttpFailure('CONFLICT','Revision reservation no longer current',409);
    revision.status=receipt?'published':'failed';revision.receipt=receipt;revision.error=d.error;
    if(receipt)change.latestRevisionId=revision.revisionId;
    this.putVersion(changeRow,change);
   }else if(d.input.kind==='composition'){
    const viewRow=this.get(d.input.viewId,'view'),view=viewDataSchema.parse(JSON.parse(viewRow.data));
    if(view.status!=='queued'||view.jobId!==id||view.manifestDigest!==d.input.manifestDigest)throw new HttpFailure('CONFLICT','View reservation no longer current',409);
    view.status=receipt?'runnable':'failed';view.receipt=receipt;view.error=d.error;
    this.putVersion(viewRow,view);
   }
   const row=this.putVersion(job,d);return{resource:this.resource(row),version:row.version};
  },id);
 }
