 private put(kind:string,id:string,owner:string,data:unknown,version=1):Row{const text=stringify(data);this.ctx.storage.sql.exec('INSERT INTO resources(id,kind,owner,version,data) VALUES(?,?,?,?,?)',id,kind,owner,version,text);return{id,kind,owner,version,data:text};}
